use cusp::{ControlPoint,potential};use numerics::symmetric_eigenvalues_2x2;use serde::{Deserialize,Serialize};use thiserror::Error;
#[derive(Clone,Copy,Debug,PartialEq,Serialize,Deserialize)]pub struct CoupledParameters{pub first:ControlPoint,pub second:ControlPoint,pub coupling:f64}#[derive(Clone,Copy,Debug,PartialEq,Serialize,Deserialize)]pub struct CoupledStatePoint{pub first:f64,pub second:f64}
#[derive(Clone,Copy,Debug,Eq,PartialEq,Serialize,Deserialize)]#[serde(rename_all="snake_case")]pub enum Stability{Stable,Saddle,Unstable,Degenerate}
#[derive(Clone,Debug,PartialEq,Serialize,Deserialize)]pub struct CoupledEquilibrium{pub state:CoupledStatePoint,pub potential:f64,pub gradient_norm:f64,pub hessian_eigenvalues:[f64;2],pub stability:Stability}
pub fn coupled_potential(s:CoupledStatePoint,p:CoupledParameters)->f64{potential(s.first,p.first)+potential(s.second,p.second)-p.coupling*s.first*s.second}pub fn gradient(s:CoupledStatePoint,p:CoupledParameters)->[f64;2]{[s.first.powi(3)-p.first.beta*s.first-p.first.alpha-p.coupling*s.second,s.second.powi(3)-p.second.beta*s.second-p.second.alpha-p.coupling*s.first]}pub fn hessian(s:CoupledStatePoint,p:CoupledParameters)->[[f64;2];2]{[[3.0*s.first*s.first-p.first.beta,-p.coupling],[-p.coupling,3.0*s.second*s.second-p.second.beta]]}
pub fn solve(p:CoupledParameters,seeds:&[CoupledStatePoint],tol:f64,max:usize)->Result<Vec<CoupledEquilibrium>,CoupledError>{if seeds.is_empty()||tol<=0.0||max==0{return Err(CoupledError::Input)}let mut roots=Vec::new();for seed in seeds{let mut s=*seed;for _ in 0..max{let g=gradient(s,p);if g[0].hypot(g[1])<=tol{break}let h=hessian(s,p);let det=h[0][0]*h[1][1]-h[0][1]*h[1][0];if det.abs()<1e-12{s.first-=0.05*g[0];s.second-=0.05*g[1]}else{let dx=(h[1][1]*g[0]-h[0][1]*g[1])/det;let dy=(-h[1][0]*g[0]+h[0][0]*g[1])/det;let damp=if dx.hypot(dy)>1.0{0.25}else{1.0};s.first-=damp*dx;s.second-=damp*dy}}let g=gradient(s,p);if g[0].hypot(g[1])>tol*10.0||roots.iter().any(|r:&CoupledEquilibrium|(r.state.first-s.first).hypot(r.state.second-s.second)<tol*10.0){continue}let h=hessian(s,p);let e=symmetric_eigenvalues_2x2(h[0][0],h[0][1],h[1][1])?;let stability=if e[0].abs()<=tol||e[1].abs()<=tol{Stability::Degenerate}else if e[0]>0.0{Stability::Stable}else if e[1]<0.0{Stability::Unstable}else{Stability::Saddle};roots.push(CoupledEquilibrium{state:s,potential:coupled_potential(s,p),gradient_norm:g[0].hypot(g[1]),hessian_eigenvalues:e,stability})}Ok(roots)}
#[derive(Debug,Error)]pub enum CoupledError{#[error("invalid coupled cusp input")]Input,#[error(transparent)]Numerical(#[from]numerics::NumericalError)}
